window.SAQ_PAPER_QUESTIONS["2016-1-northern-sydney"]=[{"number":1,"title":"","stemText":"A 42 year old man is brought by ambulance after completing a long distance bicycle race.\nSince the race his wife reports he has been acting strangely and fainted twice. She was told by his fellow cyclists that he had drunk plenty of water and had not fallen off his bike.\nHis vital signs are:\n\nTemp: 39.5 degrees (per rectal)\n\nHR:\n122 regular\n\nBP:\n100/45\n\nGCS: 14","parts":[{"id":"a","label":"Part A","prompt":"List 5 potential causes for this man’s symptoms and signs (5 marks)"},{"id":"b","label":"Part B","prompt":"List 5 investigations that you think are the most important and their rationale (10 marks) INVESTIGATION RATIONALE"},{"id":"c","label":"Part C","prompt":"The patient’s temperature rises to 41 degrees (per rectal). Outline 4 actions in your initial management (4 marks)"},{"id":"d","label":"Part D","prompt":"Despite resuscitative efforts the patient’s temperature rises to 42 degrees and he has a generalised seizure. Outline 6 treatment priorities now. Provide doses and end points where appropriate (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"> <strong>Heat stroke/heat related illness (bold mandatory) </strong></div><div class=\"answer-line\"> <strong>Hyponatraemia </strong></div><div class=\"answer-line\"> <strong>Hypoglycaemia </strong></div><div class=\"answer-line\"> Sympathomimetic syndrome and/or stimulants</div><div class=\"answer-line\"> Serotonin syndrome</div><div class=\"answer-line\"> Anticholinergic syndrome</div><div class=\"answer-line\"> Neuroleptic malignant syndrome</div><div class=\"answer-line\"> Seizure</div><div class=\"answer-line\"> Sepsis</div><div class=\"answer-line\"> Encephalitis</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">INVESTIGATION</div><div class=\"answer-line\">RATIONALE</div><div class=\"answer-line\"> <strong>BSL  </strong></div><div class=\"answer-line\"><strong>hypo/hyperglycaemia (bold mandatory) </strong></div><div class=\"answer-line\"> Na</div><div class=\"answer-line\">hyponatraemia</div><div class=\"answer-line\"> K</div><div class=\"answer-line\">hyperkalaemia (due to AKI)</div><div class=\"answer-line\"> VBG</div><div class=\"answer-line\">metabolic acidosis</div><div class=\"answer-line\"> Lactate</div><div class=\"answer-line\">shock</div><div class=\"answer-line\"> CK</div><div class=\"answer-line\">rhabdomyolsis</div><div class=\"answer-line\"> U/Cr</div><div class=\"answer-line\">AKI /dehydration</div><div class=\"answer-line\"> LFT</div><div class=\"answer-line\">ischaemic hepatitis</div><div class=\"answer-line\"> Lipase</div><div class=\"answer-line\">pancreatitis</div><div class=\"answer-line\"> UA</div><div class=\"answer-line\">myoglobinuria</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">The patient’s temperature rises to 41 degrees (per rectal). Outline 4 actions in your</div><div class=\"answer-line\">initial management (4 marks)</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\"> Passive Cooling (fan and mist, ice packs, wet towels, cooling blankets etc)</div><div class=\"answer-line\"> Active Cooling (Cooled IVF, IDC – cold water irrigation)</div><div class=\"answer-line\"> IV rehydration crystalloid</div><div class=\"answer-line\"> Rectal/core temperature</div><div class=\"answer-line\"> Supportive care</div><div class=\"answer-line\"> Chlorpromazine/Diazepam if shivering</div><div class=\"answer-line\"> IV antibiotics if sepsis suspected</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Despite resuscitative efforts the patient’s temperature rises to 42 degrees and he has a</div><div class=\"answer-line\">generalised seizure. Outline 6 treatment priorities now. Provide doses and end points</div><div class=\"answer-line\">where appropriate (6 marks)</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\"> Seizure control – benzodiazepine titrated</div><div class=\"answer-line\"> Airway support – sensible drugs and doses for RSI</div><div class=\"answer-line\"> Active cooling, aim core temp &lt;38.5</div><div class=\"answer-line\"> Rectal/Peritoneal lavage, CPB etc if no response</div><div class=\"answer-line\"> Seek and treat hyponatraemia</div><div class=\"answer-line\"> Aggressive IVF (aim UO &gt;1-2ml/kg/hr) if rhabdomyolysis</div><div class=\"answer-line\"> Diuresis and urine alkalinisation if above fails</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 51 year old lady presented having been seen in your ED 3 days ago after an MVA. A senior registrar reviewed her and a full trauma assessment was performed. No major injuries were found. She complained of foot pain prior to discharge and an x-ray was performed. The discharge letter states no fracture, and she was advised to treat this as a sprain. She represents with ongoing pain and is now unable to weight bear. AN XRAY OF THE FOOT IS SHOWN IN THE PROPS BOOKLET, PAGE 3","parts":[{"id":"a","label":"Part A","prompt":"Describe the main abnormality in this x-ray and the likely diagnosis (2 marks)"},{"id":"b","label":"Part B","prompt":"List 3 fractures which can occur in association with this injury (3 marks)"},{"id":"c","label":"Part C","prompt":"The patient is angry about the missed injury and states she is going to make a complaint. Briefly outline how you would address this complaint (6 marks)"}],"propPages":["asset:imgbf83b67ec1615248cf"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Widening of the space between 1st and 2nd MT</div><div class=\"answer-line\"></div><div class=\"answer-line\">Lis Franc injury</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"># Base of 2nd MT (most common)</div><div class=\"answer-line\"></div><div class=\"answer-line\"># Cuboid</div><div class=\"answer-line\"></div><div class=\"answer-line\"># Medial Cuneiform</div><div class=\"answer-line\"></div><div class=\"answer-line\">less common but probably ok – navicular #</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">The patient is angry about the missed injury and states she is going to make a complaint. Briefly</div><div class=\"answer-line\">outline how you would address this complaint (6 marks)</div><div class=\"answer-line\">____________________________________________________________________</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\">____________________________________________________________________</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\"></div><div class=\"answer-line\">Answer should show logical thought process to stepwise management of complaint including</div><div class=\"answer-line\">acknowledgement, investigation, documentation, quality cycle and communication with patient.</div><div class=\"answer-line\">Example as below.</div><div class=\"answer-line\"></div><div class=\"answer-line\">Senior and consistent staff member dealing with incident</div><div class=\"answer-line\"></div><div class=\"answer-line\">Identify error – ensure no harm and treat issues</div><div class=\"answer-line\"></div><div class=\"answer-line\">Acknowledge error and complaint – open disclosure, apologize without accepting liability and</div><div class=\"answer-line\">explain initial process of investigation and plan to get back to her</div><div class=\"answer-line\"></div><div class=\"answer-line\">Investigate case fully –review notes, xray, discuss with staff involved</div><div class=\"answer-line\"></div><div class=\"answer-line\">Document error – IMMS, incident notification, escalate if serious error (probably not required in</div><div class=\"answer-line\">this case)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Quality – ensure goes through Q and A cycle, M and M, address individual vs system errors.</div><div class=\"answer-line\">Implement education / system changes e.g. prompt review of rad reports in this case</div><div class=\"answer-line\"></div><div class=\"answer-line\">Meet again with patient ideally within 72 hrs and answer complaint addressing how repeat issue</div><div class=\"answer-line\">prevented.</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 26 year old man presents with a 3 day history of sharp central chest pain suggestive of\npericarditis. His observations are stable apart from a temp of 38C. THE ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 4","parts":[{"id":"a","label":"Part A","prompt":"List the ECG abnormalities (3 marks)"},{"id":"b","label":"Part B","prompt":"What ECG features would make a diagnosis of benign early repolarisation more likely? (2 marks)"},{"id":"c","label":"Part C","prompt":"List 5 causes of pericarditis (5 marks)"},{"id":"d","label":"Part D","prompt":"List 3 investigations used to detect a pericardial effusion in this setting - include a\nbrief description of the positive finding for each investigation (6 marks)"}],"propPages":["asset:img16a4f964f1f2b53847"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Sinus tachycardia</div><div class=\"answer-line\"></div><div class=\"answer-line\">Concave STE inf and V4-6</div><div class=\"answer-line\"></div><div class=\"answer-line\">PR depression inf &amp; V4-6</div><div class=\"answer-line\"></div><div class=\"answer-line\">Reciprocal ST depression &amp; PR elevation V1 &amp; aVR</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">What ECG features would make a diagnosis of benign early repolarisation more</div><div class=\"answer-line\">likely? (2 marks)</div><div class=\"answer-line\">_______________________________________________________________________________</div><div class=\"answer-line\">_______________________________________________________________________________</div><div class=\"answer-line\"></div><div class=\"answer-line\">ST elevation limited to the precordial leads</div><div class=\"answer-line\"></div><div class=\"answer-line\">Absence of PR depression</div><div class=\"answer-line\"></div><div class=\"answer-line\">Prominent T waves</div><div class=\"answer-line\"></div><div class=\"answer-line\">Changes do not evolve over time</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">uraemia</div><div class=\"answer-line\"></div><div class=\"answer-line\">viral infection (all causes of myocarditis)</div><div class=\"answer-line\"></div><div class=\"answer-line\">bacterial infection</div><div class=\"answer-line\"></div><div class=\"answer-line\">radiation</div><div class=\"answer-line\"></div><div class=\"answer-line\">malignancy (metastatic: lung&gt;breast&gt;leukaemia and lymphoma&gt;melanoma)</div><div class=\"answer-line\"></div><div class=\"answer-line\">vasculitis</div><div class=\"answer-line\"></div><div class=\"answer-line\">autoimmune (SLE, RA, scleroderma, sarcoid…)</div><div class=\"answer-line\"></div><div class=\"answer-line\">TB</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>List 3 investigations used to detect a pericardial effusion in this setting – include a brief</td><td>description of the positive finding for each investigation (6 marks)</td></tr><tr><td>_______________________________________________________________________________</td><td>_______________________________________________________________________________</td></tr><tr><td>_______________________________________________________________________________</td><td>_______________________________________________________________________________</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"You are at a peripheral hospital with no maternity facilities when a 16 year old obese girl presents in the second stage of labour. Up until this presentation she was unaware that she was pregnant.","parts":[{"id":"a","label":"Part A","prompt":"List 5 steps you would take to prepare for her delivery (5 marks)\nWithin minutes of arrival the baby’s head is delivered. However on the next contraction you are unable to deliver the shoulders despite gentle axial traction."},{"id":"b","label":"Part B","prompt":"Name this condition and in what period of time should the baby be delivered to avoid serious foetal hypoxia (2 marks)"},{"id":"c","label":"Part C","prompt":"Describe 3 manoeuvres that may enable the safe delivery of the child (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"> Any 5 of the below</div><div class=\"answer-line\"> Resuscitation room, get help, staff with midwifery/obstetric experience, 2 teams mother</div><div class=\"answer-line\">and baby,</div><div class=\"answer-line\"> Baby resuscitation equipment and staff, resuscitaire, heater, blankets, bag valve mask-</div><div class=\"answer-line\">on air, dose of adrenaline, correct sized airway,breathing equipment. Umbilical line</div><div class=\"answer-line\"> Mother-monitoring, delivery pack, pain relief, iv access bloods, syntocinon for post</div><div class=\"answer-line\">delivery, ultrasound to exclude multiple birth?</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Name this condition and in what period of time should the baby be delivered to</div><div class=\"answer-line\">avoid serious foetal hypoxia (2 marks)</div><div class=\"answer-line\"> Shoulder dystocia</div><div class=\"answer-line\"></div><div class=\"answer-line\">5 minutes (accept &lt; 10 min)</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"> Answer any  3 of the following</div><div class=\"answer-line\"> MacRobert’s manoeuvre; Lie mother flat 2 staff members flex and abduct the hips until</div><div class=\"answer-line\">the thighs are on the abdomen (opens up and straightens the birth canal)</div><div class=\"answer-line\"> Suprapubic pressure; to adduct the foetus’ shoulder and thus narrow the width and to</div><div class=\"answer-line\">rotate the shoulders into the oblique axis (assistant presses from the foetus back in a</div><div class=\"answer-line\">downward and lateral manner)</div><div class=\"answer-line\"> Internal rotation; “vaginal access should be gained posteriorly, into the sacral hollow.</div><div class=\"answer-line\">The whole hand should be entered posteriorly to perform internal rotation or delivery of</div><div class=\"answer-line\">the posterior arm. The woman should be brought to the end of the bed, or the end of</div><div class=\"answer-line\">the bed should be removed, to make vaginal access easier. Delivery can then be</div><div class=\"answer-line\">facilitated by rotation into an oblique diameter or when possible by a full 180 degree</div><div class=\"answer-line\">rotation of the fetal trunk”</div><div class=\"answer-line\"> Delivery of the posterior arm: “The fetal wrist should be grasped and the posterior arm</div><div class=\"answer-line\">should be gently withdrawn from the vagina in a straight line”</div><div class=\"answer-line\"> Epiosotomy ; mainly to allow for getting the hand in.</div><div class=\"answer-line\"> Putting mother in “all fours” position (on hands and knees)</div><div class=\"answer-line\"> Cleidotomy ; division of symphysis pubis</div><div class=\"answer-line\"> Zavanelli manoeuvre; pushing the head back in and doing a caesarean</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A concerned first-time mother has brought her 2-week-old baby to the ED because the baby is jaundiced.","parts":[{"id":"a","label":"Part A","prompt":"What is the name of the pathological condition caused by neonatal jaundice? (1 mark)"},{"id":"b","label":"Part B","prompt":"If left untreated, what are 2 sequelae of this condition? (2 marks)"},{"id":"c","label":"Part C","prompt":"List 2 benign causes of neonatal jaundice (2 marks)"},{"id":"d","label":"Part D","prompt":"List 4 pathological causes of neonatal jaundice (4 marks)"},{"id":"e","label":"Part E","prompt":"What 5 historical features will guide your assessment of this child? (5 marks)"},{"id":"f","label":"Part F","prompt":"How can a serum bilirubin assist your assessment? (2 marks)"},{"id":"g","label":"Part G","prompt":"List 5 other investigations you might consider (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">What is the name of the pathological condition caused by neonatal jaundice?      (1</div><div class=\"answer-line\">mark)</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\"> Kernicterus - chronic bilirubin encephalopathy</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"> Acute: seizures, coma</div><div class=\"answer-line\"> Chronic: cerebral palsy, developmental delay, death</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"> Normal physiological jaundice due to ?immature hepatocytes</div><div class=\"answer-line\"> Breast milk jaundice – Can last up to a couple of weeks, tends to be settling by week 3</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"> Sepsis (onset anytime)</div><div class=\"answer-line\"> Haemolysis: Rhesus, ABO (onset usually in 1st 24h)</div><div class=\"answer-line\"> Liver trouble e.g. hepatitis, congenital abnormality e.g. biliary atresia, metabolic e.g.</div><div class=\"answer-line\">alpha-1 antitrypsin deficiency</div><div class=\"answer-line\"> Bowel obstruction</div><div class=\"answer-line\"> Hypothyroidism</div><div class=\"answer-line\"> Other e.g. breakdown of blood from cephalhaematoma</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"> Prematurity</div><div class=\"answer-line\"> Time of onset</div><div class=\"answer-line\"> Duration of symptoms &gt; 3/52</div><div class=\"answer-line\"> Obstructive symptoms – pale stools, dark urine, vomiting</div><div class=\"answer-line\"> Duration of symptoms &gt; 3/52</div><div class=\"answer-line\"> Signs of lethargy eg poor suck</div><div class=\"answer-line\"> Formula feed?</div><div class=\"answer-line\"> Symptoms of sepsis ?fever</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\"> The higher the total bilirubin level, the greater the risk. Interpretation depends on</div><div class=\"answer-line\">prematurity (term babies handle higher levels)</div><div class=\"answer-line\"> Conjugated versus unconjugated bilirubin. Conjugated is bad because it indicates an</div><div class=\"answer-line\">obstructive cause.</div></section><section class=\"answer-part\"><h5>Part G</h5><div class=\"answer-line\"> Sepsis – FBC, CRP, blood and urine culture, LP</div><div class=\"answer-line\"> Hemolysis - FBC &amp; film again, group &amp; hold, haptoglobins, LDH, Coombs test, G6PD</div><div class=\"answer-line\"> Tests for liver function/obstruction – LFT, US</div><div class=\"answer-line\"> TFT</div><div class=\"answer-line\"> Other – serum ammonia, pyruvate, lactate</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 65 year old woman presents to ED with lower back pain and normal observations. She has\na history of type 2 diabetes but is otherwise well. There is no history of trauma.","parts":[{"id":"a","label":"Part A","prompt":"List 6 historical features which may suggest serious pathology (6 marks)"},{"id":"b","label":"Part B","prompt":"After taking your history you are concerned about possible cauda equina syndrome. List 4 examination findings which would support your diagnosis (4 marks)"},{"id":"c","label":"Part C","prompt":"List the most important immediate investigation and the most important treatment if this condition is confirmed (2 marks)"},{"id":"d","label":"Part D","prompt":"List the most common cause, and 2 other causes for cauda equina syndrome (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Bladder or bowel symptoms</div><div class=\"answer-line\"></div><div class=\"answer-line\">Weakness</div><div class=\"answer-line\"></div><div class=\"answer-line\">Sensory changes</div><div class=\"answer-line\"></div><div class=\"answer-line\">Fever</div><div class=\"answer-line\"></div><div class=\"answer-line\">Known Malignancy</div><div class=\"answer-line\"></div><div class=\"answer-line\">Weight Loss</div><div class=\"answer-line\"></div><div class=\"answer-line\">IVDU</div><div class=\"answer-line\"></div><div class=\"answer-line\">Thoracic back pain</div><div class=\"answer-line\"></div><div class=\"answer-line\">Night pain – increased likelihood of malignancy</div><div class=\"answer-line\"></div><div class=\"answer-line\">Steroid use</div><div class=\"answer-line\"></div><div class=\"answer-line\">History of Osteoporosis</div><div class=\"answer-line\"></div><div class=\"answer-line\">Recent invasive procedure to back – eg steroid injection / LP</div><div class=\"answer-line\"></div><div class=\"answer-line\">History of Spinal stenosis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Urinary Retention</div><div class=\"answer-line\"></div><div class=\"answer-line\">Saddle Anaesthesia</div><div class=\"answer-line\"></div><div class=\"answer-line\">Loss of perianal sensation</div><div class=\"answer-line\"></div><div class=\"answer-line\">Loss of anal tone</div><div class=\"answer-line\"></div><div class=\"answer-line\">Leg Weakness</div><div class=\"answer-line\"></div><div class=\"answer-line\">Diminished reflexes</div><div class=\"answer-line\"></div><div class=\"answer-line\">Sensory Changes in the legs</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Investigation: urgent MRI</div><div class=\"answer-line\"></div><div class=\"answer-line\">Treatment: urgent surgical decompression (Neurosurg consultation probably acceptable)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Large central disc prolapse / rupture</div><div class=\"answer-line\"></div><div class=\"answer-line\">Malignancy – tumour pressing on cord</div><div class=\"answer-line\"></div><div class=\"answer-line\">Spinal infection</div><div class=\"answer-line\"></div><div class=\"answer-line\">Epidural Haematoma</div><div class=\"answer-line\"></div><div class=\"answer-line\">Trauma</div><div class=\"answer-line\"></div><div class=\"answer-line\">Spinal stenosis</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 62 year old male is brought to ED by ambulance after falling 4 metres from a ladder,\nsustaining a head injury. Primary survey is unremarkable apart from a significant head injury. There is an obvious swelling to the left side of his face and it is difficult to open his left eye. Observations are:\n\nHR 100, BP 100/60, SaO2 99% RA, RR 16, GCS 6","parts":[{"id":"a","label":"Part A","prompt":"You elect to undertake an RSI to secure his airway prior to imaging. Complete the tables below:"},{"id":"b","label":"Part B","prompt":"List 2 possible sedative drugs and doses you could use to facilitate RSI (4 marks)"},{"id":"c","label":"Part C","prompt":"List one potential positive and one potential negative aspect of each drug’s pharmacodynamics in this patient (4 marks) Drug Dose Positive pharmacodynamics specific to head injured patient Negative pharmacodynamics specific to head injured patient"},{"id":"d","label":"Part D","prompt":"List 4 positive findings from the 2 axial CT images (4 marks)\n2 AXIAL IMAGES OF A CT BRAIN ARE SHOWN IN THE PROPS BOOKLET, PAGE 5 & 6"},{"id":"e","label":"Part E","prompt":"Neurosurgery review the patient and are keen to take the patient to theatre urgently. A lateral canthotomy is also suggested. List 3 signs in an unconscious patient that would suggest a need for urgent lateral canthotomy (3 marks)"}],"propPages":["asset:img393627a4311fbed209","asset:imgd65aaa388de88e0c06"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"> Suggest ketamine and thiopentone most appropriate answer</div><div class=\"answer-line\"> Propofol inappropriate as more likely to cause hypotension</div><div class=\"answer-line\"> Other answers could be accepted if rationalised</div><div class=\"answer-line\">b) List one potential positive and one potential negative aspect of each drug’s</div><div class=\"answer-line\">pharmacodynamics in this patient (4 marks)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Ketamine</td><td>Thiopentone</td><td></td></tr><tr><td>Dose</td><td>Suggest lower end of dose</td><td>3-5mg/kg, suggest lower</td></tr><tr><td>spectrum as drowsy –</td><td>end</td><td></td></tr><tr><td colspan=\"3\">probably 1mg/kg</td></tr><tr><td>Positive pharmacodynamics</td><td>Maintains BP which is</td><td>Cerebroprotective function</td></tr><tr><td>specific to head injured patient</td><td>important in head injury. As</td><td></td></tr><tr><td colspan=\"3\">Anticonvulsant</td></tr><tr><td colspan=\"3\">even one episode of</td></tr><tr><td colspan=\"3\">hypotension associated with</td></tr><tr><td colspan=\"3\">worse outcome</td></tr><tr><td colspan=\"3\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</td></tr><tr><td>Negative pharmacodynamics</td><td>Some statement re previous</td><td>Significant chance of</td></tr><tr><td>specific to head injured patient</td><td>concern about possible</td><td>hypotension especially if</td></tr><tr><td>increased ICP with</td><td>inappropriate large dose</td><td></td></tr><tr><td>ketamine. Although good</td><td>used</td><td></td></tr><tr><td colspan=\"3\">candidates would state that</td></tr><tr><td colspan=\"3\">more recent evidence</td></tr><tr><td colspan=\"3\">would suggest probably safe</td></tr><tr><td colspan=\"3\">May need to use</td></tr><tr><td colspan=\"3\">(reflecting current common</td></tr><tr><td colspan=\"3\">vasopressor post induction</td></tr><tr><td colspan=\"3\">use in retrieval medicine</td></tr><tr><td colspan=\"3\">eg metaraminol</td></tr><tr><td colspan=\"3\">especially)</td></tr><tr><td colspan=\"3\">ii.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>2 AXIAL IMAGES OF A CT BRAIN ARE SHOWN IN THE PROPS BOOKLET, PAGE 5 &amp; 6</strong></div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\"> Large right sided parieto-occipital subdural haematoma</div><div class=\"answer-line\"> Significant midline shift with effacement of ventricles</div><div class=\"answer-line\"> Left zygomatic fracture, nasal bone fractures, fractures through walls of left maxillary</div><div class=\"answer-line\">sinus</div><div class=\"answer-line\"> Left facial swelling and proptosis, difficult to appreciate from single image but significant</div><div class=\"answer-line\">retrobulbar haemorrhage</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div><div class=\"answer-line\">iii.</div><div class=\"answer-line\">Neurosurgery review the patient and are keen to take the patient to theatre urgently. A</div><div class=\"answer-line\">lateral canthotomy is also suggested. List 3 signs in an unconscious patient that would</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"> Raised intra ocular pressure &gt;40mmHg in unconscious patient with retrobulbar</div><div class=\"answer-line\">haemorrhage (normal pressure is 10-21)</div><div class=\"answer-line\"> RAPD</div><div class=\"answer-line\"> Dilated pupil in absence of central cause and CT suggesting retrobulbar haematoma</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Negative pharmacodynamics</td><td>Some statement re previous</td><td>Significant chance of</td></tr><tr><td>specific to head injured patient</td><td>concern about possible</td><td>hypotension especially if</td></tr><tr><td>increased ICP with</td><td>inappropriate large dose</td><td></td></tr><tr><td>ketamine. Although good</td><td>used</td><td></td></tr><tr><td colspan=\"3\">candidates would state that</td></tr><tr><td colspan=\"3\">more recent evidence</td></tr><tr><td colspan=\"3\">would suggest probably safe</td></tr><tr><td colspan=\"3\">May need to use</td></tr><tr><td colspan=\"3\">(reflecting current common</td></tr><tr><td colspan=\"3\">vasopressor post induction</td></tr><tr><td colspan=\"3\">use in retrieval medicine</td></tr><tr><td colspan=\"3\">eg metaraminol</td></tr><tr><td colspan=\"3\">especially)</td></tr><tr><td colspan=\"3\">ii.</td></tr><tr><td colspan=\"3\"><strong>2 AXIAL IMAGES OF A CT BRAIN ARE SHOWN IN THE PROPS BOOKLET, PAGE 5 &amp; 6</strong></td></tr><tr><td colspan=\"3\">___________________________________________________________________________</td></tr><tr><td colspan=\"3\">___________________________________________________________________________</td></tr><tr><td colspan=\"3\">___________________________________________________________________________</td></tr><tr><td colspan=\"3\">___________________________________________________________________________</td></tr><tr><td colspan=\"3\"> Large right sided parieto-occipital subdural haematoma</td></tr><tr><td colspan=\"3\"> Significant midline shift with effacement of ventricles</td></tr><tr><td colspan=\"3\"> Left zygomatic fracture, nasal bone fractures, fractures through walls of left maxillary</td></tr><tr><td colspan=\"3\">sinus</td></tr><tr><td colspan=\"3\"> Left facial swelling and proptosis, difficult to appreciate from single image but significant</td></tr><tr><td colspan=\"3\">retrobulbar haemorrhage</td></tr><tr><td colspan=\"3\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</td></tr><tr><td colspan=\"3\">iii.</td></tr><tr><td colspan=\"3\">___________________________________________________________________________</td></tr><tr><td colspan=\"3\">___________________________________________________________________________</td></tr><tr><td colspan=\"3\">___________________________________________________________________________</td></tr><tr><td colspan=\"3\"> Raised intra ocular pressure &gt;40mmHg in unconscious patient with retrobulbar</td></tr><tr><td colspan=\"3\">haemorrhage (normal pressure is 10-21)</td></tr><tr><td colspan=\"3\"> RAPD</td></tr><tr><td colspan=\"3\"> Dilated pupil in absence of central cause and CT suggesting retrobulbar haematoma</td></tr><tr><td colspan=\"3\"> Normal indications of decreased acuity, significant pain and ophthalmoplegia – not</td></tr><tr><td colspan=\"3\">appropriate answers for this question as patient has low GCS</td></tr><tr><td colspan=\"3\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"You have agreed to be the expedition doctor for a trek to the Everest base camp. (altitude 5300m)","parts":[{"id":"a","label":"Part A","prompt":"Outline the proposed pathophysiology of: Acute Mountain Sickness (AMS)/High Altitude Cerebral Oedema (2 marks) High Altitude Pulmonary Oedema (2 marks)"},{"id":"b","label":"Part B","prompt":"List 2 risk factors for the development of High Altitude Pulmonary Oedema at any given\naltitude (2 marks)"},{"id":"c","label":"Part C","prompt":"List 5 clinical features of AMS (5 marks)"},{"id":"d","label":"Part D","prompt":"For severe High Altitude Pulmonary Oedema, list 4 treatment options (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Outline the proposed pathophysiology of:</div><div class=\"answer-line\">Acute Mountain Sickness (AMS)/High Altitude Cerebral Oedema (2 marks)</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\"></div><div class=\"answer-line\">Vasogenic cerebral oedema. Hypoxia appears to cause cerebral vasodilatation, leading to</div><div class=\"answer-line\">increased cerebral blood volume and blood flow.</div><div class=\"answer-line\"></div><div class=\"answer-line\">Leaky BBB – due to loss of autoregulation and increased permeability.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">List 2 risk factors for the development of High Altitude Pulmonary Oedema at any given altitude</div><div class=\"answer-line\">(2 marks)</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\">____________________________________________________________________</div><div class=\"answer-line\"></div><div class=\"answer-line\">Rapid ascent</div><div class=\"answer-line\"></div><div class=\"answer-line\">Genetic predisposition</div><div class=\"answer-line\"></div><div class=\"answer-line\">Any pre-existing pulmonary hypertension (e.g. previous VTE/PE, cardiac shunts – e.g. ASD)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Exertion</div><div class=\"answer-line\"></div><div class=\"answer-line\">Cold</div><div class=\"answer-line\"></div><div class=\"answer-line\">Use of sleeping medication</div><div class=\"answer-line\"></div><div class=\"answer-line\">Excessive salt ingestion</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Headache – worse with bending over or valsalva</div><div class=\"answer-line\"></div><div class=\"answer-line\">Anorexia, nausea, sometimes vomiting</div><div class=\"answer-line\"></div><div class=\"answer-line\">Lassitude, weakness, irritability</div><div class=\"answer-line\"></div><div class=\"answer-line\">Retinal haemorrhages</div><div class=\"answer-line\"></div><div class=\"answer-line\">Fluid retention - peripheral/facial oedema</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Immediate descent</div><div class=\"answer-line\"></div><div class=\"answer-line\">Oxygen</div><div class=\"answer-line\"></div><div class=\"answer-line\">Minimise exertion</div><div class=\"answer-line\"></div><div class=\"answer-line\">Nifedipine</div><div class=\"answer-line\"></div><div class=\"answer-line\">Portable hyperbaric compression chamber</div><div class=\"answer-line\"></div><div class=\"answer-line\">CPAP/EPAP mask</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"You are on duty in a small urban district hospital. You attend to an 8 year-old boy who was rescued from the bottom of a saltwater backyard pool, unconscious. He was resuscitated by pre-hospital personnel and presents with the following vital signs:\n\nHR 72\nbpm, regular\n\nBP 90/60 mmHg\n\nRR 24\nbpm\n\nSaO2\n100 % on high flow oxygen","parts":[{"id":"a","label":"Part A","prompt":"Outline 5 key features in your examination of this child (5 marks)"},{"id":"b","label":"Part B","prompt":"List 5 factors which determine this child’s prognosis (5 marks)"},{"id":"c","label":"Part C","prompt":"The child’s GCS improves to 14. Despite high flow “non-rebreather” mask oxygen, he shows signs of respiratory distress from aspiration pneumonitis. Complete the table\n• utlining 3 escalating modalities that could be used to improve his oxygenation.\nDescribe initial"},{"id":"d","label":"Part D","prompt":"List 4 potential disadvantages of the use of non-invasive mask ventilation (CPAP or\nBiPAP) for this child in the aero-medical retrieval context (4 marks) BOOK TWO"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Temperature</div><div class=\"answer-line\"></div><div class=\"answer-line\">Signs of lung injury/aspiration from immersion</div><div class=\"answer-line\"></div><div class=\"answer-line\">Signs of perfusion/haemodynamics</div><div class=\"answer-line\"></div><div class=\"answer-line\">Neurological deficit</div><div class=\"answer-line\"></div><div class=\"answer-line\">Evidence of C spine injury</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Immersion time</div><div class=\"answer-line\"></div><div class=\"answer-line\">Water temperature</div><div class=\"answer-line\"></div><div class=\"answer-line\">Presence of CPR and effectiveness</div><div class=\"answer-line\"></div><div class=\"answer-line\">Response to resus/ROSC prehospital</div><div class=\"answer-line\"></div><div class=\"answer-line\">Neurological state/GCS prehospital</div><div class=\"answer-line\"></div><div class=\"answer-line\">Comorbidities</div><div class=\"answer-line\"></div><div class=\"answer-line\">Intercurrent traumatic injuries</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">The child’s GCS improves to 14. Despite high flow “non-rebreather” mask oxygen, he shows</td></tr><tr><td colspan=\"2\">signs of respiratory distress from aspiration pneumonitis. Complete the table outlining 3</td></tr><tr><td colspan=\"2\">escalating modalities that could be used to improve his oxygenation. Describe initial settings</td></tr><tr><td colspan=\"2\">and sizes as appropriate (6 marks)</td></tr><tr><td>Treatment/modality</td><td>Settings</td></tr><tr><td>High Flow humidified nasal</td><td>FiO2 variable using blender – start 0.21 &amp; titrate</td></tr><tr><td>prong O2</td><td>up. Increasing CPAP type effect with increasing flow</td></tr><tr><td colspan=\"2\">rate. 8 year old estimate 30kg – usual “formula” is</td></tr><tr><td colspan=\"2\">2L/kg/min flow but max is 60L/min. Start at 6L/min</td></tr><tr><td colspan=\"2\">&amp; titrate up</td></tr><tr><td>NIV</td><td>mask CPAP or BiPAP high FiO2 (&gt;0.6 or more??),</td></tr><tr><td colspan=\"2\">10/5 or similar</td></tr><tr><td>Invasive</td><td>6mm cuffed ETT, 5-7ml/kg TV</td></tr><tr><td colspan=\"2\"></td></tr><tr><td colspan=\"2\">Bag-mask oxygen with PEEP valve</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>List 4 potential disadvantages of the use of non-invasive mask ventilation (CPAP or BiPAP)</td><td></td><td></td></tr><tr><td>for this child in the aero-medical retrieval context (4 marks)</td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td>huge O2 supply required (may not be feasible)</td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td>limited evidence for effectiveness in non-cardiogenic pulm oedema or aspiration syndromes</td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td>may delay “proper’ treatment</td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td>mask potentially claustrophobic/uncomfortable in an already scary aero-med environment</td><td></td><td></td></tr><tr><td></td><td>air insufflation  increase risk of emesis</td><td></td></tr><tr><td>Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</td><td></td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"(24 marks) - DOUBLE QUESTION Ambulance officers are bringing a 5-month old baby to your ED, in cardiac arrest. You have a few minutes to prepare your drugs and equipment.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table below (10 marks) Formula/calculation Answer Estimated weight ETT size DC shock joules Adrenaline dose 10% glucose dose"},{"id":"b","label":"Part B","prompt":"Complete the table below identifying the recommended compression:ventilation ratio for each group (3 marks) Group Ratio Neonatal Paediatric Adult"},{"id":"c","label":"Part C","prompt":"Briefly explain the rationale for different compression ratios in these populations (2 marks)"},{"id":"d","label":"Part D","prompt":"Briefly explain why the ratio recommended for lay provider BLS is constant across age groups (1 mark)"},{"id":"e","label":"Part E","prompt":"The child regains spontaneous circulation but is agitated and requires a rapid sequence induction. Please list the drugs you will choose, including doses (6 marks) Drug Dose/kg Dose"},{"id":"f","label":"Part F","prompt":"Increasingly cuffed endotracheal tubes are used in paediatric intubations. Briefly explain why, historically, uncuffed tubes were preferred (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">(24 marks) – DOUBLE QUESTION</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Complete the table below identifying the recommended compression:ventilation</td><td>ratio for each (3 marks)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Briefly explain the rationale for different compression ratios in these populations (2</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\">____________________________________________________________________</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\"> Younger population more likely to have asphyxia cause of arrest so increased</div><div class=\"answer-line\">emphasis on ventilation (A/B) versus compressions (C)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Briefly explain why the ratio recommended for lay provider BLS is constant across</div><div class=\"answer-line\">age groups (1 mark)</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\"> Simply an attempt to reduce confusion &amp; increase bystander CPR attempts</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">The child regains spontaneous circulation but is agitated and requires a rapid</div><div class=\"answer-line\">sequence induction. Please list the drugs you will choose, including doses (6 marks)</div><div class=\"answer-line\">Drug</div><div class=\"answer-line\">Dose/kg</div><div class=\"answer-line\">Dose</div><div class=\"answer-line\"> Sedation</div><div class=\"answer-line\">o thiopentone need low dose eg 1mg/kg</div><div class=\"answer-line\">o propofol similar eg 1mg/kg</div><div class=\"answer-line\">o ketamine 1-2mg/kg</div><div class=\"answer-line\">o can probably use other alternatives too</div><div class=\"answer-line\"> Paralysis</div><div class=\"answer-line\">o sux then 1.5mg/kg is pretty standard</div><div class=\"answer-line\">o roc then should give similar or slightly less</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Increasingly cuffed endotracheal tubes are used in paediatric intubations. Briefly explain</div><div class=\"answer-line\">why, historically, uncuffed tubes were preferred (2 marks)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Narrowest part of paed airway subglottic. Older paed ETTs had small volume, high pressure</div><div class=\"answer-line\">cuffs made of poorly tolerated materials leading to tracheal injury &amp; subsequent subglottic</div><div class=\"answer-line\">stenosis. Newer devices have larger volume, lower pressure cuffs</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 75 year old man has been resuscitated following an out-of-hospital cardiac arrest. He has been taken to a small regional Emergency Department. He was intubated at scene. His past history is unknown but paramedics have brought a bag of his normal medications: frusemide, spironolactone, digoxin and warfarin. THE PATIENT’S ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 7","parts":[{"id":"a","label":"Part A","prompt":"What are the 3 main findings in this ECG? (3 marks)"},{"id":"b","label":"Part B","prompt":"List 3 potential causes of the dysrhythmia in this patient (3 marks)"},{"id":"c","label":"Part C","prompt":"A retrieval team has been dispatched by helicopter with an estimated flight time of 2 hours. For the safe transfer of this patient, list the minimum monitoring modalities required (5 marks)"},{"id":"d","label":"Part D","prompt":"Complete the following table, listing 3 common issues with the helicopter transport environment and their potential effects on patient assessment/"}],"propPages":["asset:imgb795e6a0476d05a03c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"> Inferior STEMI</div><div class=\"answer-line\"> Complete heart block</div><div class=\"answer-line\"> Widespread anterolateral ST depression</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"> Ischaemia/STEMI</div><div class=\"answer-line\"> Electrolyte abnormality – especially K</div><div class=\"answer-line\"> Digoxin toxicity</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">A retrieval team has been dispatched by helicopter with an estimated flight time of 2</div><div class=\"answer-line\">hours. For the safe transfer of this patient, list the minimum monitoring modalities</div><div class=\"answer-line\">required (5 marks)</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">__________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\"> Pulse oximetry</div><div class=\"answer-line\"> Capnography</div><div class=\"answer-line\"> Ventilation failure/disconnect alarm</div><div class=\"answer-line\"> ECG/cardiac monitoring</div><div class=\"answer-line\"> Invasive BP</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Issue</th><th>Management</th></tr></thead><tbody><tr><td>Complete the following table, listing 3 common issues with the helicopter transport</td><td></td></tr><tr><td>environment and their potential effects on patient assessment/management (6 marks)</td><td></td></tr><tr><td>Issue</td><td>Effects</td></tr><tr><td>Altitude</td><td>Decrease partial pressure  hypoxaemia (effect on patient &amp;</td></tr><tr><td>staff/crew), gas expansion (may worsen e.g. PTx, intracranial air)</td><td></td></tr><tr><td>Noise</td><td>Can’t auscultate, unable to hear equipment alarms, can’t</td></tr><tr><td>communicate with patient</td><td></td></tr><tr><td>Movement/Vibration</td><td>Motion sick doctor, patient emesis, clinical signs obscured (e.g.</td></tr><tr><td>pulses, pneumothorax), monitor (e.g. sats, NIBP) dysfunction, loose</td><td></td></tr><tr><td>equipment items become missiles</td><td></td></tr><tr><td>Temperature</td><td></td></tr><tr><td>Ambient light</td><td></td></tr><tr><td>Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 36 year old woman presents with a very sudden onset severe headache 5 hours ago. It is\nsuspicious for subarachnoid haemorrhage (SAH).","parts":[{"id":"a","label":"Part A","prompt":"(i) Apart from headache, list 4 other clinical features that may be present in SAH (4 marks)"},{"id":"b","label":"Part B","prompt":"(ii) Complete the table providing estimates where indicated (3 marks) Situation Estimate Prevalence of confirmed SAH in a patient with a classic history of “thunderclap” headache Sensitivity of new generation CT scanning in detecting SAH in this setting Incidence of “traumatic tap” when performing a lumbar puncture (LP) (iii) The CT scan of this patient is reported as normal and a decision made to perform a lumbar puncture to look for xanthochromia. Name the two red cell breakdown products that can cause yellow discolouration of CSF (2 marks) (iv) List 5 criteria that indicate that a CT scan should be carried out prior to lumbar puncture (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Onset during strenuous exercise</div><div class=\"answer-line\"></div><div class=\"answer-line\">Neck pain</div><div class=\"answer-line\"></div><div class=\"answer-line\">Neck stiffness</div><div class=\"answer-line\"></div><div class=\"answer-line\">Photophobia</div><div class=\"answer-line\"></div><div class=\"answer-line\">Transient or prolonged decrease in consciousness</div><div class=\"answer-line\"></div><div class=\"answer-line\">Seizures</div><div class=\"answer-line\"></div><div class=\"answer-line\">Nausea/vomiting</div><div class=\"answer-line\"></div><div class=\"answer-line\">Focal neurological signs</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Situation</td><td>Estimate</td></tr><tr><td>Prevalence of confirmed SAH in a patient with a classic</td><td>25% (20-30)</td></tr><tr><td colspan=\"2\">history of “thunderclap” headache</td></tr><tr><td>Sensitivity of new generation CT scanning in detecting</td><td>About 98% (90-99)</td></tr><tr><td colspan=\"2\">SAH in this setting</td></tr><tr><td>Incidence of “traumatic tap” when performing a</td><td>15-20%</td></tr><tr><td colspan=\"2\">lumbar puncture (LP)</td></tr><tr><td colspan=\"2\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</td></tr><tr><td colspan=\"2\">(iii) The CT scan of this patient is reported as normal and a decision made to perform a lumbar</td></tr><tr><td colspan=\"2\">puncture to look for xanthochromia. Name the two red cell breakdown products that can cause</td></tr><tr><td colspan=\"2\">yellow discolouration of CSF (2 marks)</td></tr><tr><td colspan=\"2\"></td></tr><tr><td colspan=\"2\">Bilirubin</td></tr><tr><td colspan=\"2\"></td></tr><tr><td colspan=\"2\">Oxy-haemoglobin</td></tr><tr><td colspan=\"2\">(iv) List 5 criteria that indicate that a CT scan should be carried out prior to lumbar puncture (5</td></tr><tr><td colspan=\"2\">marks)</td></tr><tr><td colspan=\"2\"></td></tr><tr><td colspan=\"2\">Signs of RICP – papilloedema, bradycardia/hypertension</td></tr><tr><td colspan=\"2\"></td></tr><tr><td colspan=\"2\">GCS &lt; 14 (this number variable)</td></tr><tr><td colspan=\"2\"></td></tr><tr><td colspan=\"2\">Immunosuppression</td></tr><tr><td colspan=\"2\"></td></tr><tr><td colspan=\"2\">Focal neuro deficit</td></tr><tr><td colspan=\"2\"></td></tr><tr><td colspan=\"2\">New onset seizures</td></tr><tr><td colspan=\"2\"></td></tr><tr><td colspan=\"2\">History of CNS disease (mass lesion, AVM etc)</td></tr><tr><td colspan=\"2\"></td></tr><tr><td colspan=\"2\">Older age</td></tr><tr><td colspan=\"2\"></td></tr><tr><td colspan=\"2\">Suspected SAH</td></tr><tr><td colspan=\"2\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 72 year old male is brought to ED by family with pain and swelling in his left calf for the\nlast 24 hours. He has a history of myelodysplasia and denies trauma. On examination the\ncalf is swollen and tender.","parts":[{"id":"a","label":"Part A","prompt":"List 4 possible causes of his calf pain (4 marks)\nIn the ED, the patient continues to complain of pain despite opiate analgesia. His leg is increasingly swollen and now is erythematous with palpable crepitus. Vital signs are as follows:\n\nGCS 15\n\nTemp 37.8C\n\nHR 120\n\nBP 66/40\n\nSats 96% RA"},{"id":"b","label":"Part B","prompt":"List your immediate management priorities in this patient. Include drugs, doses and end points where appropriate (5 marks)"},{"id":"c","label":"Part C","prompt":"List 3 risk factors for this condition (3 marks)"},{"id":"d","label":"Part D","prompt":"The patient’s hypotension remains refractory to fluid treatment and you decide to start vasoactive therapy. Give an example of a suitable medication for this patient with typical dosing/concentrations and treatment end points (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"> DVT</div><div class=\"answer-line\"> Cellulitis/infection</div><div class=\"answer-line\"> Ruptured bakers cyst</div><div class=\"answer-line\"> Muscle tear/tendon rupture</div><div class=\"answer-line\"> Ischaemia/embolism</div><div class=\"answer-line\"> Venous insufficiency</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">List your immediate management priorities in this patient. Include drugs, doses and end</div><div class=\"answer-line\">points where appropriate (5 marks)</div><div class=\"answer-line\">__________________________________________________________________________</div><div class=\"answer-line\">__________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\"> Move to monitored/resus area</div><div class=\"answer-line\"> IV access/Fluid resuscitation (sensible approach)</div><div class=\"answer-line\"> Empiric antibiotic treatment for nec fasc</div><div class=\"answer-line\">o Meropenem 1g IV q8h</div><div class=\"answer-line\">o Vancomycin (dependent on renal function) but usually 1g to 1.5g IV initially</div><div class=\"answer-line\">o +/- clindamycin 600mg IV q8h</div><div class=\"answer-line\"> Analgesia (sensible)</div><div class=\"answer-line\"> Monitor fluid balance</div><div class=\"answer-line\"> Urgent surgical consultation</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"> Immunosuppression from any cause including; diabetes, malignancy, alcoholism, IV drug</div><div class=\"answer-line\">use, chronic diseases such as HIV, organ transplant or any immunosuppressive therapy</div><div class=\"answer-line\"> Trauma</div><div class=\"answer-line\"> Surgery</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">The patient’s hypotension remains refractory to fluid treatment and you decide to start</div><div class=\"answer-line\">vasoactive therapy. Give an example of a suitable medication for this patient with typical</div><div class=\"answer-line\">dosing/concentrations and treatment end points (3 marks)</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\"> Noradrenaline either 4mg or 6mg in 100mls 5% dextrose – start at anywhere from 1 to 5</div><div class=\"answer-line\">mls/hr and titrate to MAP 65-70, end organ perfusion – UO &gt;0.5mls/kg/hr,</div><div class=\"answer-line\"> Adrenaline either  4mg or 6mg in 100mls 5% dextrose – start at 1 to 5 mls/hr and titrate</div><div class=\"answer-line\">to MAP &gt;65, end organ perfusion.  Can be used peripherally if no CVC.</div><div class=\"answer-line\"> Metaraminol – 10mg in 20mls saline, boluses of 0.5 to 1mg peripherally to increase SBP</div><div class=\"answer-line\">as temporary measure only</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 5 month old boy brought in by his parents appears breathless and is “off his feeds.” Your provisional impression is bronchiolitis.","parts":[{"id":"a","label":"Part A","prompt":"Name three common organisms which cause this illness (3 marks)"},{"id":"b","label":"Part B","prompt":"List 4 clinical features which would indicate a severe episode warranting admission (4\nmarks)"},{"id":"c","label":"Part C","prompt":"Complete the following table describing the rationale for each investigation in a child with bronchiolitis (3 marks) Investigation Indication/Rationale Chest Xray Nasopharyngeal aspirate Blood gas"},{"id":"d","label":"Part D","prompt":"This illness is contagious. List 2 ways to reduce transmission in hospital (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">RSV, human metapneumovirus, parainfluenza virus, influenza virus, adenovirus, enteroviruses,</div><div class=\"answer-line\">rhinovirus</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Increased irritability or lethargy</div><div class=\"answer-line\"></div><div class=\"answer-line\">Marked increase in respiratory rate</div><div class=\"answer-line\"></div><div class=\"answer-line\">Marked chest wall retraction</div><div class=\"answer-line\"></div><div class=\"answer-line\">O2 sats &lt; 90% on room air</div><div class=\"answer-line\"></div><div class=\"answer-line\">Poor feeding</div><div class=\"answer-line\"></div><div class=\"answer-line\">Apnoeic episodes (or history of same from home)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Complete the following table describing the rationale for each investigation in a child</td><td>with bronchiolitis (3 marks)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Barrier nursing: wear gloves and gown. Face shield if resp droplets likely to contaminate face</div><div class=\"answer-line\"></div><div class=\"answer-line\">Frequent hand decontamination  with gel – wash with soap 1st if soiled</div><div class=\"answer-line\"></div><div class=\"answer-line\">Isolate patient in the ED and ward</div><div class=\"answer-line\"></div><div class=\"answer-line\">Wipe equipment &amp; environment with suitable disinfectants</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 27 year old man climbed over an electricity sub-station fence and sustained an electrical injury while grabbing a metal pole with his right hand. He arrives 30 minutes later complaining of tingling in his right arm and a numb left foot. A CLINICAL PHOTOGRAPH IS SHOWN IN THE PROPS BOOKLET, PAGE 8","parts":[{"id":"a","label":"Part A","prompt":"Describe the wound seen on the foot (1 mark) Question continues next page"},{"id":"b","label":"Part B","prompt":"Complete the table outlining factors that determine the severity of an electrical injury (8 marks)"},{"id":"c","label":"Part C","prompt":"For each of the three categories below, what specific injuries or problems may occur in the patient described in the stem? For each, describe the patho-physiological process (6 marks) Injury Pathophysiology Cardiac Nervous system Limb/soft tissue"}],"propPages":["asset:imge7407a02adf08b1ecc"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Deep, full thickness burn to plantar aspect forefoot</div><div class=\"answer-line\"></div><div class=\"answer-line\">Depressed central area with surrounding eschar</div><div class=\"answer-line\"></div><div class=\"answer-line\">Sensible answer</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">____________________________________________________________________</div><div class=\"answer-line\">_____________________________________________________________________</div><div class=\"answer-line\"></div><div class=\"answer-line\">Deep, full thickness burn to plantar aspect forefoot</div><div class=\"answer-line\"></div><div class=\"answer-line\">Depressed central area with surrounding eschar</div><div class=\"answer-line\"></div><div class=\"answer-line\">Sensible answer</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>For each of the three categories below, what specific injuries or problems may occur in the</td><td>patient described in the stem?  For each, describe the pathophysiological process (6 marks)</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"An 80yr female presents via ambulance from her GP to your ED. She has a 24 hour history of vomiting, followed by syncope this morning. She had a second syncope at her GPs office and was noted to be bradycardic on ambulance arrival. Observations on arrival to ED are:\n\nGCS 15\n\nHR 76\n\nBP 85/30\n\nRR 18\n\nSaO2 96% RA\nShe describes no chest pain, has had a recent course of antibiotics for a chest infection and has started on a “new drug for my memory”. THE PATIENT’S AMBULANCE RHYTHM STRIP AND ARRIVAL ECG ARE SHOWN IN THE PROPS BOOKLET, PAGE 9 & 10","parts":[{"id":"a","label":"Part A","prompt":"List 3 relevant findings from the 12 lead ECG (3 marks)"},{"id":"b","label":"Part B","prompt":"List 3 causes of the ECG abnormalities in this patient (3 marks)"},{"id":"c","label":"Part C","prompt":"List your management priorities (4 marks)\nShe becomes bradycardic to 35 again, and her BP drops to 75/30 with a rhythm matching\nthe initial ambulance ECG strip."},{"id":"d","label":"Part D","prompt":"What is her likely diagnosis? (1 mark)"},{"id":"e","label":"Part E","prompt":"You decide to initiate transcutaneous pacing for her transfer to ICU. Outline your approach (5 marks)"}],"propPages":["asset:imgc51774a3287571ae40","asset:img003ef83b910a955ba7"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"> Sinus rhythm</div><div class=\"answer-line\"> PR prolongation</div><div class=\"answer-line\"> QT prolongation</div><div class=\"answer-line\"> No ischaemic changes</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"> Electrolytes</div><div class=\"answer-line\"> Drugs (must provide a relevant example) eg cholinergic agents, macrolide, psychotropic</div><div class=\"answer-line\">agents</div><div class=\"answer-line\"> Myocardial ischaemia</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"> Seek and treat cause – medications, AMI, electrolytes</div><div class=\"answer-line\"> Address hypotension – fluids, inotropes</div><div class=\"answer-line\"> Continuous monitoring</div><div class=\"answer-line\"> Cardiology consult/admission</div><div class=\"answer-line\"> Apply pacing pads and consider temporary/chemical pacing if further bradycardia</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"> Complete heart block</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">You decide to initiate transcutaneous pacing for her transfer to ICU. Outline your</div><div class=\"answer-line\">approach (5 marks)</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\"> Inform and consent</div><div class=\"answer-line\"> Analgesia/sedation as required – sensible options</div><div class=\"answer-line\"> Technique-</div><div class=\"answer-line\">o AP pads</div><div class=\"answer-line\">o Set rate (60-80)</div><div class=\"answer-line\">o Start pacing and slowly increase mA until pacing rate captured on monitor</div><div class=\"answer-line\">o Ensure mechanical capture</div><div class=\"answer-line\">o If pacing not captured, consider increasing current or re-siting electrodes</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 40-year-old female who is Day 3 post-partum has been brought in following increasing\nconfusion and agitation at home. In the ambulance she had a generalised tonic-clonic seizure which stopped with 5mg IMI midazolam. When you arrive she is being nursed on a bed in the Resuscitation Room. On examination: Airway: snoring / partly obstructed\n\nRR 40, O2 saturations 95%\n\nHR 130, BP 180/100\nDecreased LOC - drowsy, post-ictal, GCS 9","parts":[{"id":"a","label":"Part A","prompt":"Apart from eclampsia, list the causes of seizure you would consider in this patient (4 marks)"},{"id":"b","label":"Part B","prompt":"List 3 risk factors for pre-eclampsia/eclampsia (3 marks)"},{"id":"c","label":"Part C","prompt":"What examination features would increase your level of suspicion that this seizure is eclamptic in origin? (3 marks)"},{"id":"d","label":"Part D","prompt":"Outline your initial management in each category below. Include drugs/dose/route (where appropriate) that you would administer (6 marks) Category Management General management & resuscitation Pharmacotherapy of eclampsia/pre-eclampsia"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Apart from eclampsia, list the causes of seizure you would consider in this patient</div><div class=\"answer-line\">(4 marks)</div><div class=\"answer-line\"> <strong>Cerebral venous sinus thrombosis </strong></div><div class=\"answer-line\"> <strong>Meningoencephalitis</strong> e.g. post-epidural</div><div class=\"answer-line\"> Primary epilepsy</div><div class=\"answer-line\"> Hypoxia e.g. due to pulmonary embolus</div><div class=\"answer-line\"> TTP</div><div class=\"answer-line\"> Plus at least one not directly related to pregnancy / delivery: e.g., hypoglycaemia, toxic</div><div class=\"answer-line\">ingestion, structural intracranial e.g. bleed, ICH/SAH</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"> Nulliparity</div><div class=\"answer-line\"> Family history of preeclampsia, previous preeclampsia and eclampsia</div><div class=\"answer-line\"> Poor outcome of previous pregnancy, including intrauterine growth</div><div class=\"answer-line\">retardation, abruptio placentae, or fetal death</div><div class=\"answer-line\"> Multifetal gestations, hydatid mole, fetal hydrops, primigravida</div><div class=\"answer-line\"> Teen pregnancy</div><div class=\"answer-line\"> Primigravida</div><div class=\"answer-line\"> Patient older than 35 years</div><div class=\"answer-line\"> Lower socioeconomic status</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">What examination features would increase your level of suspicion that this seizure is</div><div class=\"answer-line\">eclamptic in origin? (3 marks)</div><div class=\"answer-line\"> Hypertension</div><div class=\"answer-line\"> Peripheral oedema</div><div class=\"answer-line\"> Hyper-reflexia  Clonus</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Outline your initial management in each category below. Include drugs/dose/route</div><div class=\"answer-line\">(where appropriate) that you would administer (6 marks)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 25 year old man presents 6 hours after a SCUBA dive with possible decompression\nsickness (DCS).","parts":[{"id":"a","label":"Part A","prompt":"List 6 questions specific to diving you should ask in your history (6 marks)"},{"id":"b","label":"Part B","prompt":"Complete the table listing 3 symptoms or signs of DCS in each"},{"id":"c","label":"Part C","prompt":"Complete the table contrasting DCS and Arterial Gas Embolism ("}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Dive profile (ideally from log book or computer)</div><div class=\"answer-line\">–</div><div class=\"answer-line\">depth, times, ascent rates, surface intervals, safety/decompression stops</div><div class=\"answer-line\"></div><div class=\"answer-line\">Dives in excess of tables?</div><div class=\"answer-line\"></div><div class=\"answer-line\">Multiple dives in one day?</div><div class=\"answer-line\"></div><div class=\"answer-line\">Altitude/flight since dive</div><div class=\"answer-line\"></div><div class=\"answer-line\">Any problems during descent/ascent</div><div class=\"answer-line\">–</div><div class=\"answer-line\">problems equalising? Equipment issues? Incidents?</div><div class=\"answer-line\"></div><div class=\"answer-line\">Delay to symptom onset after leaving water</div><div class=\"answer-line\"></div><div class=\"answer-line\">Previous dive experience</div><div class=\"answer-line\"></div><div class=\"answer-line\">Previous dive-related illness</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Category</td><td>Symptom/Sign</td></tr><tr><td>Neurological</td><td>Weakness, headache, paralysis, dizziness, visual disturbance,</td></tr><tr><td colspan=\"2\">ataxia, altered LOC, parasthesias</td></tr><tr><td>Other</td><td>SOB, rash, itching, joint aches, chest pain</td></tr><tr><td colspan=\"2\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</td></tr><tr><td colspan=\"2\">iii.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>DCS</td><td>AGE</td><td></td></tr><tr><td>Pathophysiology</td><td>Nitrogen bubbles forming in</td><td>Barotrauma; rapid expansion/tear of</td></tr><tr><td>tissues (pressure effects), in</td><td>pulmonary tissue – direct entry of</td><td></td></tr><tr><td>vessels (flow effects) &amp; activation</td><td>bubbles into arterial circulation</td><td></td></tr><tr><td colspan=\"3\">of inflammatory cascade</td></tr><tr><td>Time of onset</td><td>Gradual onset of neuro, MSK</td><td>Usually occur on ascent or</td></tr><tr><td>and/or skin symptoms often</td><td>immediately upon surfacing</td><td></td></tr><tr><td colspan=\"3\">within 30-60 min of surfacing –</td></tr><tr><td colspan=\"3\">nearly all within 24 hours</td></tr><tr><td colspan=\"3\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 70 year old man presents with ischaemic-sounding chest pain on a background of\nlongstanding, poorly controlled hypertension. His 12-hour troponin is normal. THE PATIENT’S ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 11","parts":[{"id":"a","label":"Part A","prompt":"List 4 abnormalities in this ECG (4 marks)"},{"id":"b","label":"Part B","prompt":"List 5 causes of ST segment elevation other than myocardial ischaemia (5 marks)"},{"id":"c","label":"Part C","prompt":"The patient is noted to have a systolic heart murmur. List 6 differential diagnoses of a systolic murmur (6 marks)"},{"id":"d","label":"Part D","prompt":"You suspect this patient has aortic stenosis. What are the physical signs that suggest severe aortic stenosis? (4 marks)"},{"id":"e","label":"Part E","prompt":"Your registrar wants to commence a nitrate infusion for this man’s angina. Outline your concerns about this plan (2 marks)"}],"propPages":["asset:img3d5b851db75ef7390c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"> Markedly increased LV voltages: huge precordial R and S waves that overlap with the</div><div class=\"answer-line\">adjacent leads</div><div class=\"answer-line\"> LVH</div><div class=\"answer-line\"> LV strain pattern with ST depression and T-wave inversions in I, aVL and V5-6</div><div class=\"answer-line\"> ST elevation in V1-3</div><div class=\"answer-line\"> Prominent U waves in V1-3</div><div class=\"answer-line\"> Left axis deviation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"> Pericarditis</div><div class=\"answer-line\"> Benign early repolarization</div><div class=\"answer-line\"> Left bundle branch block</div><div class=\"answer-line\"> Left ventricular hypertrophy</div><div class=\"answer-line\"> Ventricular aneurysm</div><div class=\"answer-line\"> Brugada syndrome</div><div class=\"answer-line\"> Ventricular paced rhythm</div><div class=\"answer-line\"> Raised intracranial pressure</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">The patient is noted to have a systolic heart murmur. List 6 differential diagnoses of a systolic</div><div class=\"answer-line\">murmur (6 marks)</div><div class=\"answer-line\"> Aortic stenosis</div><div class=\"answer-line\"> Mitral valve prolapse</div><div class=\"answer-line\"> Mitral regurgitation</div><div class=\"answer-line\"> Pulmonary stenosis</div><div class=\"answer-line\"> Tricuspid regurgitation</div><div class=\"answer-line\"> VSD</div><div class=\"answer-line\"> ASD</div><div class=\"answer-line\"> HOCM</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">You suspect this patient has aortic stenosis. What are the physical signs that suggest severe</td></tr><tr><td colspan=\"2\">aortic stenosis? (4 marks)</td></tr><tr><td></td><td>Slow rising pulse</td></tr><tr><td></td><td>S4</td></tr><tr><td></td><td>Paradoxical splitting of the second heart sound</td></tr><tr><td></td><td>Aortic thrill</td></tr><tr><td></td><td>Length and harshness of murmur</td></tr><tr><td></td><td>LVH – displaced apex beat</td></tr><tr><td></td><td>LVF – a late sign</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Your registrar wants to commence a nitrate infusion for this man’s angina. Outline your</div><div class=\"answer-line\">concerns about this plan (2 marks)</div><div class=\"answer-line\"> In severe AS, vasodilators are (relatively) contraindicated – cardiac output is preload</div><div class=\"answer-line\">dependent  (filling the thickened, stiff ventricle)</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 42-year-old man is brought to your ED by ambulance with acute confusion. His health has\nbeen deteriorating for three months, with tiredness & 10kg weight loss despite an enormous appetite. He is on no medications. Observations on arrival are:\n\nHR 140\n\nBP 180/100\n\nRR 40\n\nSaO2 100%\n\nGCS 13\n\nTemp 38.5\n\nBSL 10","parts":[{"id":"a","label":"Part A","prompt":"List the most likely diagnosis (1 mark)"},{"id":"b","label":"Part B","prompt":"List 4 differential diagnoses (4 marks)"},{"id":"c","label":"Part C","prompt":"List 4 problems that may precipitate the most likely diagnosis (4 marks)"},{"id":"d","label":"Part D","prompt":"List 5 treatment priorities in ED (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"> Thyroid storm</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"> Heat related illness</div><div class=\"answer-line\"> Intracranial SOL/haemorrhage</div><div class=\"answer-line\"> Sepsis – meningoencephalitis, other</div><div class=\"answer-line\"> Toxidrome – sympathomimetic, anticholinergic</div><div class=\"answer-line\"> Withdrawal syndromes – ethanol, benzodiazepines</div><div class=\"answer-line\">iii.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"> Sepsis</div><div class=\"answer-line\"> Acute MI</div><div class=\"answer-line\"> DKA</div><div class=\"answer-line\"> Trauma</div><div class=\"answer-line\"> IV iodinated contrast</div><div class=\"answer-line\"> Unrecognised or poorly treated hyperthyroidism</div><div class=\"answer-line\"> Ingestion thyroid hormone</div><div class=\"answer-line\"> Withdrawal of thyroid medication</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div><div class=\"answer-line\">iv.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"> Some knowledge/description of anti thyroid medications essential</div><div class=\"answer-line\"> Supportive care – ABC</div><div class=\"answer-line\"> Sedation – benzodiazepines</div><div class=\"answer-line\"> Seek and treat precipitant</div><div class=\"answer-line\"> Block peripheral effects – IV B Blocker (Propanolol, esmolol)</div><div class=\"answer-line\"> Decrease synthesis – PTU, carbimazole</div><div class=\"answer-line\"> Prevent release of hormone – iodine (after synthetic pathway blocked)</div><div class=\"answer-line\"> Corticosteroids</div><div class=\"answer-line\"> Consult endocrinology</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"Ambulance officers bring a 68 year old man with severe back pain to your ED. He is shocked (BP 80/50mm Hg). Your trainee has performed a bedside ultrasound and obtained this image. A CLINICAL IMAGE IS SHOWN IN THE PROPS BOOKLET, PAGE 12","parts":[{"id":"a","label":"Part A","prompt":"Describe the image (2 marks)"},{"id":"b","label":"Part B","prompt":"List the most likely diagnosis and one differential diagnosis (2 marks) The on-call vascular surgical registrar has asked you to continue to resuscitate the patient and get an urgent CT while he organises theatres."},{"id":"c","label":"Part C","prompt":"What is the role of CT scanning in this setting? (2 marks)"},{"id":"d","label":"Part D","prompt":"List the key steps in your ongoing resuscitation and preparation for theatres (5 marks)"}],"propPages":["asset:imgf6eb595ae0d7205baf"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Abdominal aortic aneurysm (AAA) approx 8cm (essential)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Likely to be a bleed into the wall as well (clotted blood appears bright on US)</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Ruptured AAA is most likely in this patient  </strong></div><div class=\"answer-line\"></div><div class=\"answer-line\">DDx includes all other causes of shock and back pain (eg pyelonephritis with sepsis) with a</div><div class=\"answer-line\">coincidental, and as yet unruptured, AAA.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">This depends on the institution &amp; the established practice of the vascular team.</div><div class=\"answer-line\"></div><div class=\"answer-line\">In centres where emergency AAA repairs are done by endo-vascular approach a CT scan is</div><div class=\"answer-line\">essential for planning/sizing of stent (even if some patients die in CT).</div><div class=\"answer-line\"></div><div class=\"answer-line\">In centres where open laparotomy is the only approach, a CT scan is essentially contraindicated</div><div class=\"answer-line\">as it delays OT. In this latter setting this should be explained to the vascular registrar +/- his/her</div><div class=\"answer-line\">boss</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div><div class=\"answer-line\">iv.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Prepare for OT: urgent cross match/ platelets/ FFP. (These will be required in OT.) (essential)</div><div class=\"answer-line\"></div><div class=\"answer-line\">In the meantime, permissive hypotension: keep BP high enough just to perfuse the brain eg</div><div class=\"answer-line\">90mm Hg. (essential)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Analgesia: eg small aliquots of IV morphine (essential)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Explanation to patient &amp; family</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"You are the retrieval doctor at a pre-hospital scene where there has been a single-occupant rollover MVA. The driver has been trapped for 2 hours by extensive compression of both legs by dashboard and steering column intrusion. He has chest and head injuries (GCS 7)","parts":[{"id":"a","label":"Part A","prompt":"What are the potential pathophysiological consequences of rapid release of this patient’s legs? (2 marks)"},{"id":"b","label":"Part B","prompt":"What therapies could you use to mitigate these pathophysiological consequences? (3 marks) On arrival at the nearby trauma centre, concerns are raised about the possibility of a bilateral lower leg compartment syndrome."},{"id":"c","label":"Part C","prompt":"Outline a technique for measuring compartment pressures (4 marks)"},{"id":"d","label":"Part D","prompt":"What pressure threshold would confirm suspicions of compartment syndrome? (1 mark)"},{"id":"e","label":"Part E","prompt":"The patient’s creatine kinase is 7000 IU/L. The renal registrar wants you to start a mannitol infusion to reduce renal injury from tubular deposition. List 3 disadvantages or adverse effects of mannitol in this context (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">What are the potential pathophysiological consequences of rapid release of this patient’s</div><div class=\"answer-line\">legs? (2 marks)</div><div class=\"answer-line\"> Washout of “trash” blood – cold, acidotic, myoglobin-&amp;-potassium-laden</div><div class=\"answer-line\"> Sudden acidosis &amp; K spike – risk malignant dysrhythmias</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">What therapies could you use to mitigate these pathophysiological consequences?          (3</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\"> IV access</div><div class=\"answer-line\"> Fluid (saline) pre-load</div><div class=\"answer-line\"> IV bicarbonate</div><div class=\"answer-line\"> Calcium at hand</div><div class=\"answer-line\"> Ideally intubate – with decreased LOC and chest injuries will not be able to mount</div><div class=\"answer-line\">adequate ventilatory response to sudden acid load</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">There are a few acceptable answers</div><div class=\"answer-line\"> Stryker needle – proprietary device with special needle with side ports – attaches to a</div><div class=\"answer-line\">pressure measuring component in the Stryker kit</div><div class=\"answer-line\"> “Normal” large bore needle or cannula attached to standard IV line and transduced as</div><div class=\"answer-line\">one would an arterial or CVP line (zero it etc)</div><div class=\"answer-line\"> With either device  prep skin, insert needle into muscle body of concern. Use of local</div><div class=\"answer-line\">anaesthetic is tricky as infiltration of a volume of LA could further increase compartment</div><div class=\"answer-line\">pressure</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div><div class=\"answer-line\"> Regardless of finding (in mmHg) a high clinical suspicion should nonetheless prompt</div><div class=\"answer-line\">urgent consideration of fasciotomy</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">What pressure threshold would confirm suspicions of compartment syndrome?</div><div class=\"answer-line\">(1 mark)</div><div class=\"answer-line\"> A typical threshold is around &gt; 35 mmHg</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>The patient’s creatine kinase is 7000 IU/L. The renal registrar wants you to start a</td><td>mannitol infusion to reduce renal injury from tubular deposition. List 3</td><td>disadvantages or adverse effects of mannitol in this context (3 marks)</td></tr><tr><td> lack of proven efficacy in preventing renal injury or need for dialysis (beyond that</td><td>provided by aggressive volume  increased UO)</td><td> causing big fluid shifts and contributing to hypovolaemia/hypotension are potentially</td></tr><tr><td>bad ideas in a polytrauma patient</td><td> potential haemoconcentration/increased viscosity</td><td> effects on ICP (??advantageous in this patient)</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 24 year old woman with a history of asthma presents with dyspnoea, dizziness and\npleuritic chest pain for 24 hours. She appears tired, her pulse is 135bpm, and has mottled peripheries. A CXR is performed in the resuscitation room. THE CHEST XRAY IS SHOWN IN THE PROPS BOOKLET, PAGE 13","parts":[{"id":"a","label":"Part A","prompt":"List 3 positive and 2 negative findings on the CXR (5 marks)\nPositive Negative"},{"id":"b","label":"Part B","prompt":"List 4 immediate management steps (4 marks)"},{"id":"c","label":"Part C","prompt":"List 4 complications of definitive treatment of this problem (4 marks)"}],"propPages":["asset:imgb00a2ef5b22dd133a9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Positive</div><div class=\"answer-line\">Negative</div><div class=\"answer-line\"></div><div class=\"answer-line\">Positive</div><div class=\"answer-line\">o <strong>Right PTX </strong></div><div class=\"answer-line\">o <strong>Significant tension with massive mediastinal shift  </strong></div><div class=\"answer-line\">o Flattened right hemidiaphragm</div><div class=\"answer-line\">o Small amount right pleural fluid</div><div class=\"answer-line\">o Deep sulcus</div><div class=\"answer-line\"></div><div class=\"answer-line\">Negative</div><div class=\"answer-line\">o No subcutaneous emphysema</div><div class=\"answer-line\">o No medical intervention, lines, drains etc</div><div class=\"answer-line\">o Trachea midline</div><div class=\"answer-line\">o No focal consolidation</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Immediate chest decompression</strong>, (fatal error if not mentioned)</div><div class=\"answer-line\">o needle thoracocentesis (ensure resolution), ICC if rapid, finger thoracostomy then 3</div><div class=\"answer-line\">sided occlusive dressing</div><div class=\"answer-line\"></div><div class=\"answer-line\">Ensure improvement of clinical state and vital signs</div><div class=\"answer-line\"></div><div class=\"answer-line\">Non invasive monitoring</div><div class=\"answer-line\"></div><div class=\"answer-line\">Formal ICC with underwater seal</div><div class=\"answer-line\"></div><div class=\"answer-line\">Oxygen</div><div class=\"answer-line\"></div><div class=\"answer-line\">Asthma management (nebs, IV therapy)</div><div class=\"answer-line\">iii.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Misplacement of ICC</div><div class=\"answer-line\"></div><div class=\"answer-line\">Solid organ injury</div><div class=\"answer-line\"></div><div class=\"answer-line\">Infection/empyema</div><div class=\"answer-line\"></div><div class=\"answer-line\">Haemorrhage</div><div class=\"answer-line\"></div><div class=\"answer-line\">Tube malfunction/blockage/kinking</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"You are at a peripheral hospital with no paediatric or neonatal facilities when a 23 year old female presents in advanced labour. You have been asked to care for the baby after birth.","parts":[{"id":"a","label":"Part A","prompt":"List 5 of the most important factors that the mother or baby may have that will\nincrease the risks of the infant needing resuscitation (5 marks)"},{"id":"b","label":"Part B","prompt":"List 3 ways you can estimate the gestational age of the infant (3 marks)"},{"id":"c","label":"Part C","prompt":"On delivery, the baby is limp, with poor respiratory effort and a HR of 90/min. List 5\n• f your immediate actions to resuscitate the baby (5 marks)"},{"id":"d","label":"Part D","prompt":"If this is a term infant should you resuscitate with air or a higher concentration of\n• xygen? Provide reasons for your answer (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">List 5 of the most important factors that the mother or baby may have that will</div><div class=\"answer-line\">increase the risks of the infant needing resuscitation (5 marks)</div><div class=\"answer-line\"><strong>The following is a standard list </strong></div><div class=\"answer-line\"><strong>Maternal Risk Factors</strong><strong>i</strong><strong> </strong></div><div class=\"answer-line\">• Prolonged rupture of membranes (&gt; 18 hours)</div><div class=\"answer-line\">• Bleeding in second or third trimester</div><div class=\"answer-line\">• Pregnancy-induced hypertension</div><div class=\"answer-line\">• Chronic hypertension</div><div class=\"answer-line\">• Substance abuse</div><div class=\"answer-line\">• Drug therapy (e.g. lithium, magnesium, adrenergic blocking agents, narcotics)</div><div class=\"answer-line\">• Diabetes mellitus</div><div class=\"answer-line\">• Chronic illness (e.g. anaemia, cyanotic congenital heart disease)</div><div class=\"answer-line\">• Maternal pyrexia</div><div class=\"answer-line\">• Maternal infection</div><div class=\"answer-line\">• Chorioamnionitis</div><div class=\"answer-line\">• Heavy sedation</div><div class=\"answer-line\">• Previous fetal or neonatal death</div><div class=\"answer-line\">• No antenatal care</div><div class=\"answer-line\"><strong>Fetal Risk Factors </strong></div><div class=\"answer-line\">• Multiple gestation (e.g. twins, triplets, etc.)</div><div class=\"answer-line\">• Preterm gestation (especially &lt;35 weeks)</div><div class=\"answer-line\">• Post-term gestation (&gt;41 weeks)</div><div class=\"answer-line\">• Large for dates</div><div class=\"answer-line\">• Fetal growth restriction</div><div class=\"answer-line\">• Alloimmune haemolytic disease (e.g. anti-D, anti-Kell, or other antibody known to cause haemolytic disease</div><div class=\"answer-line\">of the fetus and newborn, especially if fetal anaemia or hydrops fetalis is present)</div><div class=\"answer-line\">• Polyhydramnios, oligohydramnios</div><div class=\"answer-line\">• Reduced fetal movement before onset of labour</div><div class=\"answer-line\">• Congenital abnormalities which may affect breathing, cardiovascular function or other aspects of perinatal</div><div class=\"answer-line\">transition</div><div class=\"answer-line\">• Intrauterine infection</div><div class=\"answer-line\">• Hydrops fetalis</div><div class=\"answer-line\"><strong>Intrapartum Risk Factors </strong></div><div class=\"answer-line\">• Non-reassuring fetal heart rate patterns on CTG</div><div class=\"answer-line\">• Abnormal presentation</div><div class=\"answer-line\">• Prolapsed cord</div><div class=\"answer-line\">• Prolonged labour (or prolonged second stage of labour)</div><div class=\"answer-line\">• Precipitate labour</div><div class=\"answer-line\">• Antepartum haemorrhage (abruption, placenta praevia, vasa praevia)</div><div class=\"answer-line\">• Meconium in the amniotic fluid</div><div class=\"answer-line\">• Narcotic administration to mother within 4 hours of delivery</div><div class=\"answer-line\">• Forceps delivery</div><div class=\"answer-line\">• Vacuum-assisted (Ventouse) delivery</div><div class=\"answer-line\">• Maternal general anaesthesia</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"> Ask mother about LMP</div><div class=\"answer-line\"> Measure Fundal Height (at umbi = 20 weeks, at xiphsternum 36 weeks, halfway</div><div class=\"answer-line\">between 27 weeks)</div><div class=\"answer-line\"> Perform ultrasound measure- femur length or bpd or head circumference. Often</div><div class=\"answer-line\">ultrasound machines will correlate length with age</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">On delivery,  the baby is limp, with poor respiratory effort and a HR of 90/min. List 5</div><div class=\"answer-line\">of your immediate actions to resuscitate the baby (5 marks)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Dry, stimulate and place in a warmed resuscitation environment</div><div class=\"answer-line\"></div><div class=\"answer-line\">Open the airway, place head in neutral position</div><div class=\"answer-line\"></div><div class=\"answer-line\">Gentle suctioning to remove secretions</div><div class=\"answer-line\"></div><div class=\"answer-line\">If breathing remains inadequate, give 5 breaths via neonatal bag-valve mask</div><div class=\"answer-line\"></div><div class=\"answer-line\">Reassess breathing and HR. Ventilate at 30 breaths/min until regular breathing is</div><div class=\"answer-line\">established.</div><div class=\"answer-line\"></div><div class=\"answer-line\">If HR falls below 60, commence chest compressions</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">If this is a term infant should you resuscitate with air or a higher concentration of</div><div class=\"answer-line\">oxygen? Provide reasons for your answer (2 marks)</div><div class=\"answer-line\"> Air</div><div class=\"answer-line\"> While insufficient oxygenation can impair organ function or cause permanent injury,</div><div class=\"answer-line\">there is increasing evidence that even brief exposure to excessive oxygenation can</div><div class=\"answer-line\">be harmful to the newborn during and after resuscitation</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"This question compares lightning injury with high-voltage alternating-current injury.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table comparing lightning vs high voltage injury (10 marks) Factor Lightning High Voltage AC Current duration Current characteristics Energy level Cardiac arrest initial rhythm Tissue damage"},{"id":"b","label":"Part B","prompt":"There are several different types of lightning strike. List 2 types and briefly describe them (4 marks)"},{"id":"c","label":"Part C","prompt":"Describe 2 clinical features which are considered pathognomonic for lightning strike\n(2 marks)"},{"id":"d","label":"Part D","prompt":"List 3 other clinical features seen in lightning strike (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Factor</div><div class=\"answer-line\">High Voltage AC</div><div class=\"answer-line\">Current duration</div><div class=\"answer-line\">Brief/instantaneous (1-3ms)</div><div class=\"answer-line\">1-2 sec, may be</div><div class=\"answer-line\">prolonged/tetanic</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">There are several different types of lightning strike. List 2 types and briefly describe</div><div class=\"answer-line\">them (4 marks)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Describe 2 clinical features which are considered pathognomonic for lightning strike</div><div class=\"answer-line\">(2 marks)</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\">___________________________________________________________________________</div><div class=\"answer-line\"> Keraunoparalysis - Lightning induced (usually lower) limb paralysis with vascular spasm,</div><div class=\"answer-line\">flaccidity and loss of sensation. Impalpable peripheral pulses with mottled, blue limb.</div><div class=\"answer-line\">Usually self-limiting</div><div class=\"answer-line\"> Lichtenberg flowers - Feathery cutaneous burns</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"> Asystolic cardiac arrest due to massive depolarisation. May recover if secondary hypoxic</div><div class=\"answer-line\">arrest prevented</div><div class=\"answer-line\"> Neurological deficits: temporary extremity paralysis, loss of consciousness, confusion,</div><div class=\"answer-line\">amnesia. Usually transient. Occasional delayed and progressive disorders eg</div><div class=\"answer-line\">parkinsonism, seizures, cerebellar ataxia.</div><div class=\"answer-line\"> Cataracts, delayed</div><div class=\"answer-line\"> Tympanic membrane rupture</div><div class=\"answer-line\"> Posterior shoulder dislocations</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 67 year old male with a urethral catheter in situ for 2 months, awaiting TURP, presents\nwith a blocked IDC which has been changed. Routine pathology tests were performed.\n\nNa 137\n(135-145)\nBilirubin 5\n(3-20)\n\nK 4.3\n(3.5-5.2)\nProt 68\n(60-80)\n\nCl 104\n(95-110)\nAlb 38\n(32-46)\nBic 22\n(22-32)\nALP 585\n(30-110)\n\nUrea 5.2\n(3-8)\nGGT 47\n(9-36)\nCreat 67\n(45-90)\nALT 13\n(<55)\neGFR 94\n(>60)\nAST 39\n(12-36)","parts":[{"id":"a","label":"Part A","prompt":"List 2 possible causes for the pathology abnormality (2 marks)"},{"id":"b","label":"Part B","prompt":"List 3 further pathology tests you would perform and provide reasoning (6 marks)\nTest Clinical reasoning"},{"id":"c","label":"Part C","prompt":"List 5 malignancies that metastasize to bone (5 marks)"},{"id":"d","label":"Part D","prompt":"What type of bony metastases occurs in prostatic malignancy? (1 mark)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"> Paget’s disease</div><div class=\"answer-line\"> Bone malignancy/metastases</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Test</td><td>Clinical reasoning</td></tr><tr><td>FBC</td><td>Anaemia, concern re malignancy</td></tr><tr><td>Calcium</td><td>Bone disease/malignancy suspected</td></tr><tr><td>Prostate specific antigen</td><td>Prostatic malignancy possible</td></tr><tr><td colspan=\"2\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</td></tr><tr><td colspan=\"2\">iii.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"> Breast</div><div class=\"answer-line\"> Prostate</div><div class=\"answer-line\"> Lung</div><div class=\"answer-line\"> Thyroid</div><div class=\"answer-line\"> Kidney</div><div class=\"answer-line\">iv.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"> Sclerotic</div><div class=\"answer-line\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 67 year old woman has presented having found her blood pressure to be 205/130 on her\nhome BP machine.","parts":[{"id":"a","label":"Part A","prompt":"Define hypertensive emergency (2 marks)"},{"id":"b","label":"Part B","prompt":"An image of the patient’s retina is shown. Name two abnormalities seen (2 marks) A CLINICAL PHOTOGRAPH IS SHOWN IN THE PROPS BOOKLET, PAGE 14"},{"id":"c","label":"Part C","prompt":"List and justify 3 blood tests you might order in this patient (6 marks)\nBlood Test Justification"},{"id":"d","label":"Part D","prompt":"Acute lowering of BP in profoundly hypertensive patients is indicated in a number of specific settings. Complete the table including two medications for each condition listed (doses not required). Identify the therapeutic goal and the blood pressure target (12 marks) Diagnosis Preferred agents (2 marks each) Goal/Target (2 marks each) Aortic dissection Myocardial ischaemia Intracerebral haemorrhage"}],"propPages":["asset:img1ec06f896e4f7d05ec"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"> An acute elevation of blood pressure (typically to &gt;180/120mmHg) associated with end-</div><div class=\"answer-line\">organ damage – specifically acute effects on brain, heart, aorta, kidneys and/or eyes</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"> Flame (splinter) haemorrhages</div><div class=\"answer-line\"> Cotton wool spots</div><div class=\"answer-line\"> Papilloedema (blurred optic disc margins)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Blood Test</td><td>Justification</td></tr><tr><td>FBC</td><td>Microangiopathic RBC abnormalities/haemolysis</td></tr><tr><td>EUC</td><td>Renal injury (end-organ) – Ur/Cr +/- Na/K abnormalities</td></tr><tr><td>Troponin</td><td>Cardiac injury</td></tr><tr><td>BNP?</td><td>Heart failure/APO</td></tr><tr><td colspan=\"2\">Northern Sydney Hospitals Network 2 – SAQ paper 2016.1</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Acute lowering of BP in profoundly hypertensive patients is indicated in a number of</td><td>specific settings. Complete the table including two medications for each condition</td></tr><tr><td>listed (doses not required). Identify the therapeutic goal and the blood pressure</td><td>target (12 marks)</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
